<div class="th-auth-admin"><div class="th-auth-admin__header"><div><span class="th-auth-admin__eyebrow">Profile designer</span><h1 class="th-auth-admin__title">Extra Fields</h1><p class="th-auth-admin__subtitle">Add structured profile data without changing the users table.</p></div><?php if(auth_current_user_id()===1||user_can('auth.create_user_fields')):?><a class="th-auth-admin__button" href="<?=esc(ROOT.'/admin/auth/fields/create')?>"><i class="fa-solid fa-plus"></i> Add field</a><?php endif;?></div>
<div class="th-auth-admin__panel"><div class="th-auth-admin__table-wrap"><table class="th-auth-admin__table"><thead><tr><th>Field</th><th>Type</th><th>Visibility</th><th>Shown in</th><th>Values</th><th>Status</th><th class="th-auth-admin__right">Order</th></tr></thead><tbody><?php if(!$fields):?><tr><td colspan="7"><div class="th-auth-admin__empty">No extra fields have been created.</div></td></tr><?php endif;?><?php foreach($fields as $field):?><tr><td><a class="th-auth-admin__primary-link" href="<?=esc(ROOT.'/admin/auth/fields/'.$field->id)?>"><?=esc((string)$field->label)?></a><div class="th-auth-admin__muted"><code><?=esc((string)$field->field_key)?></code><?=$field->required?' · Required':''?></div></td><td><?=esc(auth_field_types()[(string)$field->field_type]??(string)$field->field_type)?></td><td><?=esc(auth_field_visibility_options()[(string)$field->visibility]??(string)$field->visibility)?></td><td><div class="th-auth-admin__badges"><?php if($field->show_signup):?><span class="th-auth-admin__badge">Signup</span><?php endif;?><?php if($field->show_public):?><span class="th-auth-admin__badge">Public</span><?php endif;?><?php if($field->show_private):?><span class="th-auth-admin__badge">Account</span><?php endif;?><?php if($field->show_admin):?><span class="th-auth-admin__badge">Admin</span><?php endif;?></div></td><td><?=esc((string)$field->value_count)?></td><td><span class="th-auth-admin__status th-auth-admin__status--<?=$field->active?'active':'disabled'?>"><?=$field->active?'Active':'Inactive'?></span></td><td class="th-auth-admin__right"><form class="th-auth-admin__inline" method="post" action="<?=esc(ROOT.'/admin/auth/fields/'.$field->id.'/move')?>"><?=csrf()?><button class="th-auth-admin__icon-button" name="direction" value="up" title="Move up"><i class="fa-solid fa-arrow-up"></i></button><button class="th-auth-admin__icon-button" name="direction" value="down" title="Move down"><i class="fa-solid fa-arrow-down"></i></button></form><a class="th-auth-admin__icon-button" href="<?=esc(ROOT.'/admin/auth/fields/'.$field->id)?>"><i class="fa-solid fa-pen"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div>
